    #[DataProvider('sources')]
    public function testItBecomesUjo(string $source, string $html): void
    {
        self::assertSame($html, $this->html(new HtmlReader()->read($source)->document->blocks));
    }

    public function testTheTitleAndMetaOfAPageAreItsMetadata(): void
    {
        self::assertSame(['title' => 'T', 'author' => 'Ada', 'empty' => ''], new HtmlReader()->read('<html><head><title> T </title><meta name="Author" content="Ada"><meta name="empty"><meta charset="utf-8"><link rel="x"></head><body>x</body></html>')->metadata);
        self::assertSame([], new HtmlReader()->read('<p>x</p>')->metadata);
    }

    public function testTheNormalizerCanBeReplaced(): void
    {
        $this->expectException(UnknownBlockType::class);
        new HtmlReader(new Normalizer(BlockTypeRegistry::default()->without('header')))->read('<h2>a</h2>');
    }

    public function testAnEmptySourceIsAnEmptyDocument(): void
    {
        self::assertSame([], new HtmlReader()->read('')->document->blocks);
        self::assertSame("<p class=\"ujo-paragraph\">a\u{FFFD}b</p>", $this->html(new HtmlReader()->read("a\0b")->document->blocks));
    }

    /**
     * @param list<Block> $blocks
     */
    private function html(array $blocks): string
    {
        return HtmlRenderer::default()->render(new Document($blocks));
    }
}
